style.css:
@-moz-document url-prefix("https://gemini.google.com") {
.conversation-container {
   max-width: 148rem !important; /* Original : Élargit la zone de chat */
}

.input-area-container {
   max-width: 148rem !important; /* Élargit la section d'entrée globale */
}

.text-input-field {
   max-width: none !important; /* Supprime la largeur maximale sur le champ de texte */
   width: 100% !important; /* Fait remplir l'entrée à l'espace disponible */
}

.bottom-container {
   max-width: 148rem !important; /* Assure que la barre du bas (avec l'entrée) correspond */
}

.table-block {
    max-width: 148rem !important; /* Élargit les tables dans la sortie */
}
}
